### Godot version

4.0.3 AND 4.1 RC 2

### System information

Windows 10 64 bit. Godot Mono. Ryzen 5, RX 6000, .Net 6 iirc

### Issue description

New issue after investigation from:
https://github.com/godotengine/godot/issues/78863

When you have a character spawning projectiles to shoot, and shooting with a `MoveAndSlide()` in C# in the same `_PhysicsProcess(double delta)` method, random crashes can occur that ARE NOT HANDLED BY TRY CATCH IN C#. 

SEMI INCONSISTENT BECAUSE... it can take anywhere from 3 to 160 shots for it to crash on my Ryzen 5000 PC.

![image](https://github.com/godotengine/godot/assets/32988055/cf3bb149-3818-4632-b25c-c6c4ede2631f)


### Steps to reproduce

I have a player character. If he shoots projectiles with 
![image](https://github.com/godotengine/godot/assets/32988055/28dd5962-d458-4b43-bf02-5d10dfc46284)

And you spawn it in the script below (doesn't take input directly) it will cause random crashing. 
More likely to crash when moving.
If you have a second character with the script below and shoot that character, it can also cause crashes. 

### Minimal reproduction project

As far as I can tell, it will crash with the following script at the bottom.

```cs
using Godot;
using System;

public partial class PlayerPawn : CharacterBody3D {
	public const float Speed = 5.0f;
	public const float JumpVelocity = 4.5f;

	// Get the gravity from the project settings to be synced with RigidBody nodes.
	public static float gravity = ProjectSettings.GetSetting("physics/3d/default_gravity").AsSingle();

	Vector2 inputDir = Vector2.Zero;

	[Export]
	public Camera3D camera;
    [Export]
    float mouseSensitivity = .003f;
	[Export]
	PackedScene bb;
	[Export]
	Node3D bbSpawn;

	bool hitAndOut = false;

	bool shooting = false;
	static double[] shootingDelay = { .2, .4, .6 };

	public void SetHitAndOut(bool newValue) {
		hitAndOut = newValue;
    }

    public void ReceiveInput(ClientToServerControllerInput input, bool pressed) {

		if (hitAndOut) {
			shooting = false;
			inputDir = Vector2.Zero;
            return;
        }

        switch (input) {
			case ClientToServerControllerInput.MoveForward:
				if (pressed)
					inputDir.Y -= 1;
				else
					inputDir.Y += 1;
				break;
			case ClientToServerControllerInput.MoveBackward:
				if (pressed)
					inputDir.Y += 1;
				else
					inputDir.Y -= 1;
                break;
			case ClientToServerControllerInput.MoveLeft:
				if (pressed)
					inputDir.X -= 1;
				else
					inputDir.X += 1;
                break;
			case ClientToServerControllerInput.MoveRight:
				if (pressed)
					inputDir.X += 1;
				else
					inputDir.X -= 1;
                break;
			case ClientToServerControllerInput.Shoot:
				if (pressed) shooting = true;
				else shooting = false;
				break;
			default:
				break;
		}
	}

	public void ReceiveLookInput(Vector2 mouseMovement) {
        RotateObjectLocal(Vector3.Down, mouseMovement.X * mouseSensitivity);
        camera.RotateObjectLocal(Vector3.Left, mouseMovement.Y * mouseSensitivity);
    }

	double shootTimer = 0.0;
	public override void _PhysicsProcess(double delta) {
		

        #region shooting
        shootTimer += delta;
        if (shooting && shootTimer >= shootingDelay[0]) {
			shootTimer = 0.0;
			BB newBB = bb.Instantiate<BB>();
            newBB.Position = bbSpawn.GlobalPosition;
            newBB.Rotation = bbSpawn.GlobalRotation;
            GetParent().AddChild(newBB);
            //GlobalTransform.Basis.GetEuler();

        }
		#endregion


		#region movement
		//Vector3 velocity = Velocity;
		Vector3 velocity;
		velocity.X = inputDir.X;
		velocity.Z = inputDir.Y;
		velocity.Y = 0;

		// Add the gravity.
		if (!IsOnFloor())
			velocity.Y -= gravity * (float)delta;

        // Get the input direction and handle the movement/deceleration.
        // As good practice, you should replace UI actions with custom gameplay actions.
        //Vector2 inputDir = Input.GetVector("ui_left", "ui_right", "ui_up", "ui_down");
		Vector3 direction = (Transform.Basis * new Vector3(inputDir.X, 0, inputDir.Y)).Normalized();
		if (direction != Vector3.Zero) {
			velocity.X = direction.X * Speed;
			velocity.Z = direction.Z * Speed;
		}
		else {
			velocity.X = Mathf.MoveToward(Velocity.X, 0, Speed);
			velocity.Z = Mathf.MoveToward(Velocity.Z, 0, Speed);
		}

		velocity.Rotated(Vector3.Up, Rotation.Y);

		Velocity = velocity;
		try {
			MoveAndSlide();
		}
		catch (Exception e) { }
        #endregion
    }
}```
